mapper.select:

select #{start} time,reject_num controlNum,monitor_num monitorNum,CONVERT(c2s_byte_len*8/300,int)+CONVERT(s2c_byte_len*8/300,int) networkFlowNum,CONVERT(c2s_byte_len*8/300,int) upstreamNum,CONVERT(s2c_byte_len*8/300,int) downstreamNum,
  new_uni_conn_num newLinkNum,live_conn_num activeConNum,drop_conn_num dropConNum,loop_conn_num refluxConNum
  from NTC_TOTAL_REPORT
  WHERE report_time >= #{start}
  AND report_time < #{end}


      	SELECT #{start} time,entrance_id area,service type,SUM(sum) count
      	FROM ntc_entrance_report
          WHERE report_time >= #{start}
          AND report_time < #{end}
	    GROUP BY entrance_id,service
	    HAVING  service BETWEEN #{a} AND #{b}
		or service BETWEEN #{c} AND #{d}
		or service BETWEEN #{e} AND #{f};

SELECT #{start} time,entrance_id area,sum(sum) count
FROM ntc_entrance_report

  WHERE report_time >= #{start}
  AND report_time < #{end}

  AND service = 18
group by entrance_id;

SELECT  #{start} time ,service type,SUM(sum)  count
FROM ntc_service_report

  WHERE report_time >= #{start}
  AND report_time < #{end}

GROUP BY service;

      SELECT #{start} time,entrance_id area, s_ip src_ip, d_ip dst_ip,service type,SUM(sum) count
	    FROM ntc_service_behav_statistic

          WHERE report_time >= #{start}
          AND report_time < #{end}

	    GROUP BY s_ip,d_ip,service,entrance_id

SELECT #{start} time,service,entrance_id area,sum(sum) count
FROM ntc_entrance_report

   WHERE report_time >= #{start}
   AND report_time < #{end}

 GROUP BY entrance_id
 HAVING service between #{a} and #{b}
 or service between #{c} and #{d}
 or service between #{e} and #{f}

select report_time
  FROM ntc_total_report

  WHERE report_time < #{end}

  ORDER BY report_time desc
  LIMIT 1;

select report_time
  FROM ntc_entrance_report

  WHERE report_time < #{end}

  ORDER BY report_time desc
  LIMIT 1;

select report_time
  FROM ntc_entrance_report

  WHERE report_time < #{end}
  AND service = 18

  ORDER BY report_time desc
  LIMIT 1;

select report_time
  FROM ntc_service_report

  WHERE report_time < #{end}

  ORDER BY report_time desc
  LIMIT 1;

select report_time
  FROM ntc_service_behav_statistic

  WHERE report_time < #{end}

  ORDER BY report_time desc
  LIMIT 1;

select report_time
  FROM ntc_entrance_report

  WHERE report_time < #{end}

  ORDER BY report_time desc
  LIMIT 1;
